package com.bank.flink.model;

import java.time.LocalDateTime;

// Keyed state per account: count within the current one-minute window.
public class WindowState {
    private LocalDateTime windowStart;
    private int count;

    public WindowState(LocalDateTime windowStart) { this.windowStart = windowStart; this.count = 0; }
    public LocalDateTime getWindowStart() { return windowStart; }
    public int getCount() { return count; }
    public void increment() { count++; }
    public void reset(LocalDateTime newStart) { this.windowStart = newStart; this.count = 1; }
}
