package com.bank.flink.engine;

import com.bank.flink.model.*;
import java.time.Duration;
import java.time.LocalDateTime;
import java.util.*;
import java.util.logging.Logger;

// Simulates Flink: per-event processing, keyed windowed state, checkpoint/restore.
public class FlinkStyleProcessor {
    private static final Logger log = Logger.getLogger(FlinkStyleProcessor.class.getName());

    private final int maxPerWindow;
    private final Duration windowSize;
    // Keyed state: accountId → its current window state.
    private Map<String, WindowState> keyedState = new HashMap<>();

    public FlinkStyleProcessor(int maxPerWindow, Duration windowSize) {
        this.maxPerWindow = maxPerWindow;
        this.windowSize = windowSize;
    }

    // Called once per event as it ARRIVES (record-at-a-time).
    public void processElement(Event e) {
        WindowState state = keyedState.get(e.getAccountId());
        if (state == null || isNewWindow(state, e.getEventTime())) {
            keyedState.put(e.getAccountId(), state = new WindowState(e.getEventTime()));
            state.increment();
        } else {
            state.increment();
        }
        log.info(() -> "EVENT " + e.getAccountId() + " amt=" + e.getAmount()
                + " windowCount=" + keyedState.get(e.getAccountId()).getCount());

        if (keyedState.get(e.getAccountId()).getCount() > maxPerWindow) {
            log.severe(() -> "FRAUD ALERT: " + e.getAccountId()
                    + " exceeded " + maxPerWindow + " swipes within " + windowSize.toSeconds() + "s");
        }
    }

    private boolean isNewWindow(WindowState s, LocalDateTime now) {
        return Duration.between(s.getWindowStart(), now).compareTo(windowSize) >= 0;
    }

    // CHECKPOINT: snapshot keyed state for exactly-once recovery.
    public Map<String, WindowState> checkpoint() {
        log.info("CHECKPOINT: snapshotting keyed state");
        return new HashMap<>(keyedState);
    }

    // RESTORE: recover state after a simulated failure.
    public void restore(Map<String, WindowState> snapshot) {
        this.keyedState = new HashMap<>(snapshot);
        log.warning("RESTORED keyed state from checkpoint");
    }
}
