package com.bank.flink;

import com.bank.flink.engine.FlinkStyleProcessor;
import com.bank.flink.model.*;
import java.math.BigDecimal;
import java.time.Duration;
import java.time.LocalDateTime;
import java.util.*;
import java.util.logging.Logger;

public class FlinkDemo {
    private static final Logger log = Logger.getLogger(FlinkDemo.class.getName());

    public static void main(String[] args) {
        LocalDateTime t = LocalDateTime.of(2024, 10, 29, 10, 0, 0);
        FlinkStyleProcessor proc = new FlinkStyleProcessor(3, Duration.ofSeconds(60));

        List<Event> stream = List.of(
            new Event("SAV2001", new BigDecimal("1200"), t),
            new Event("CUR3001", new BigDecimal("5000"), t.plusSeconds(5)),
            new Event("SAV2001", new BigDecimal("900"),  t.plusSeconds(10)),
            new Event("SAV2001", new BigDecimal("700"),  t.plusSeconds(20)),
            new Event("SAV2001", new BigDecimal("600"),  t.plusSeconds(30)) // 4th → alert
        );

        for (int i = 0; i < stream.size(); i++) {
            proc.processElement(stream.get(i));
            if (i == 2) { // simulate a checkpoint + crash + restore mid-stream
                Map<String, WindowState> snap = proc.checkpoint();
                proc.restore(snap);
            }
        }
    }
}
